        const q = await this.navigate(record.index);
        assert(q.signature === record.signature, '第 ' + record.index + ' 题与已检查题干不一致。');
        if (record.submitted || questionReadonly(q)) { this.log('第 ' + record.index + ' 题已提交/只读，跳过。'); continue; }
